 update public.vault_draw_events set user_id = target_id where user_id = source_id;
 update public.vault_events set user_id = target_id where user_id = source_id;

 -- A new authoritative Steam import begins after the callback. Preserve any
 -- verified job already in flight and discard the source staging payload.
 delete from public.steam_import_jobs where user_id = source_id;

 perform public.refresh_catalog_import_metrics(
 array(select steam_appid from pg_temp.manual_merge_catalog_appids),
 null
 );

 update public.app_users
 set
 display_name = coalesce(nullif(trim(p_steam_display_name), ''), display_name),
 avatar_url = coalesce(nullif(trim(p_avatar_url), ''), avatar_url),
 last_login_at = now(),
 updated_at = now()
 where id = target_id;

 insert into public.sessions (user_id, token_hash, expires_at)
 values (target_id, p_new_session_token_hash, p_new_session_expires_at);

 insert into public.account_merges (
 source_account_id,
 target_account_id,
 verified_steam_id,
 merge_mode
 ) values (
 source_id,
 target_id,
 p_verified_steam_id,
 'merged_existing'
 );

 update public.manual_profile_security_intents
 set
 consumed_at = now(),
 target_account_id = target_id,
 verified_steam_id = p_verified_steam_id,
 openid_response_nonce = p_openid_response_nonce,
 outcome = 'merged_existing'
 where id = intent_row.id;

 delete from public.manual_steam_profiles where id = source_id;
 delete from public.app_accounts where id = source_id;

 result_mode := 'merged_existing';
 return query select target_id, result_mode, source_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_api_rate_limit(p_bucket text, p_key_hash text, p_limit integer, p_window_seconds integer)
 RETURNS TABLE(allowed boolean, remaining integer, retry_after_seconds integer)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 v_now timestamptz := clock_timestamp();
 v_window_started_at timestamptz;
 v_request_count integer;
begin
 if p_bucket is null or p_bucket !~ '^[a-z0-9_]{1,64}$' then
 raise exception 'INVALID_RATE_LIMIT_BUCKET';
 end if;
 if p_key_hash is null or p_key_hash !~ '^[0-9a-f]{64}$' then
 raise exception 'INVALID_RATE_LIMIT_KEY';
 end if;
 if p_limit is null or p_limit < 1 or p_limit > 10000 then
 raise exception 'INVALID_RATE_LIMIT';
 end if;
 if p_window_seconds is null or p_window_seconds < 10 or p_window_seconds > 86400 then
 raise exception 'INVALID_RATE_LIMIT_WINDOW';
 end if;

 insert into public.api_rate_limits as current_limit (
 bucket,
 key_hash,
 window_started_at,
 request_count,
 updated_at
 ) values (
 p_bucket,
 p_key_hash,
 v_now,
 1,
 v_now
 )
 on conflict (bucket, key_hash) do update
 set
 window_started_at = case
 when current_limit.window_started_at <= v_now - make_interval(secs => p_window_seconds)
 then v_now
 else current_limit.window_started_at
 end,
 request_count = case
 when current_limit.window_started_at <= v_now - make_interval(secs => p_window_seconds)
 then 1
 else least(current_limit.request_count + 1, p_limit + 1)
 end,
 updated_at = v_now
 returning current_limit.window_started_at, current_limit.request_count
 into v_window_started_at, v_request_count;

 return query select
 v_request_count <= p_limit,
 greatest(0, p_limit - v_request_count),
 case
 when v_request_count <= p_limit then 0
 else greatest(
 1,
 ceil(extract(epoch from (
 v_window_started_at + make_interval(secs => p_window_seconds) - v_now
 )))::integer
 )
 end;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_manual_profile_security_intent(p_source_account_id uuid, p_source_manual_session_id uuid, p_token_hash text, p_expires_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 created_intent_id uuid;
begin
 if p_source_account_id is null or p_source_manual_session_id is null then
 raise exception 'LINK_SESSION_MISSING';
 end if;
 if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
 raise exception 'LINK_INTENT_INVALID';
 end if;
 if p_expires_at is null
 or p_expires_at <= now()
 or p_expires_at > now() + interval '15 minutes' then
 raise exception 'LINK_INTENT_INVALID';
 end if;

 perform pg_advisory_xact_lock(hashtextextended('manual-link:' || p_source_account_id::text, 0));

 if not exists (
 select 1
 from public.manual_profile_sessions as sessions
 join public.manual_steam_profiles as profiles
 on profiles.id = sessions.profile_id
 where sessions.id = p_source_manual_session_id
 and sessions.profile_id = p_source_account_id
 and sessions.expires_at > now()
 ) then
 raise exception 'LINK_SESSION_MISMATCH';
 end if;

 update public.manual_profile_security_intents
 set consumed_at = now(), outcome = 'expired'
 where source_account_id = p_source_account_id
 and consumed_at is null
 and expires_at <= now();

 insert into public.manual_profile_security_intents (
 source_account_id,
 source_manual_session_id,
 token_hash,
 expires_at
 ) values (
 p_source_account_id,
 p_source_manual_session_id,
 p_token_hash,
 p_expires_at
 )
 returning id into created_intent_id;

 return created_intent_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_or_resume_manual_profile_session(p_steam_id text, p_profile_url text, p_display_name text, p_steam_display_name text, p_avatar_url text, p_token_hash text, p_expires_at timestamp with time zone)
 RETURNS TABLE(id uuid, steam_id text, display_name text, steam_display_name text, avatar_url text, resumed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 selected_profile public.manual_steam_profiles%rowtype;
 created_id uuid;
 profile_existed boolean := false;
begin
 if p_steam_id is null or p_steam_id !~ '^[0-9]{17}$' then
 raise exception 'INVALID_MANUAL_STEAM_ID';
 end if;
 if p_profile_url is distinct from 'https://steamcommunity.com/profiles/' || p_steam_id then
 raise exception 'INVALID_MANUAL_PROFILE_URL';
 end if;
 if p_display_name is null or char_length(trim(p_display_name)) not between 1 and 80 then
 raise exception 'INVALID_MANUAL_DISPLAY_NAME';
 end if;
 if p_steam_display_name is null or char_length(trim(p_steam_display_name)) not between 1 and 80 then
 raise exception 'INVALID_STEAM_DISPLAY_NAME';
 end if;
 if p_avatar_url is not null and char_length(p_avatar_url) > 2048 then
 raise exception 'INVALID_MANUAL_AVATAR_URL';
 end if;
 if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
 raise exception 'INVALID_MANUAL_SESSION_TOKEN';
 end if;
 if p_expires_at is null or p_expires_at <= now() or p_expires_at > now() + interval '370 days' then
 raise exception 'INVALID_MANUAL_SESSION_EXPIRY';
 end if;

 -- Shared with verified Steam sign-in/profile promotion so account-type changes
 -- and public-URL sign-ins cannot race for the same Steam identity.
 perform pg_advisory_xact_lock(hashtextextended('steam:' || p_steam_id, 0));

 select profiles.*
 into selected_profile
 from public.manual_steam_profiles as profiles
 where profiles.steam_id = p_steam_id
 order by profiles.created_at desc, profiles.id desc
 limit 1
 for update;

 if found then
 profile_existed := true;
 update public.manual_steam_profiles as profiles
 set
 steam_display_name = trim(p_steam_display_name),
 avatar_url = coalesce(nullif(trim(p_avatar_url), ''), profiles.avatar_url),
 updated_at = now()
 where profiles.id = selected_profile.id
 returning profiles.* into selected_profile;
 else
 created_id := gen_random_uuid();
 insert into public.app_accounts (id, account_type)
 values (created_id, 'manual');

 insert into public.manual_steam_profiles (
 id,
 steam_id,
 steam_profile_url,
 display_name,
 steam_display_name,
 avatar_url
 ) values (
 created_id,
 p_steam_id,
 p_profile_url,
 trim(p_display_name),
 trim(p_steam_display_name),
 nullif(trim(p_avatar_url), '')
 )
 returning * into selected_profile;
 end if;

 insert into public.manual_profile_sessions (profile_id, token_hash, expires_at)
 values (selected_profile.id, p_token_hash, p_expires_at);

 return query
 select
 selected_profile.id,
 selected_profile.steam_id,
 selected_profile.display_name,
 selected_profile.steam_display_name,
 selected_profile.avatar_url,
 profile_existed;
end;
$function$

