CREATE OR REPLACE FUNCTION public.pin_scoped_user_game(p_user_id uuid, p_game_id uuid, p_scope text DEFAULT 'library'::text, p_replace_game_id uuid DEFAULT NULL::uuid)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare next_slot smallint; replace_slot smallint; result uuid[];
begin
 if p_scope not in ('library', 'wishlist') then raise exception 'INVALID_PIN_SCOPE'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text || ':' || p_scope, 0));
 if not exists (select 1 from public.user_games where id = p_game_id and user_id = p_user_id and ((p_scope = 'library' and ownership = 'Owned' and status in ('Not Started','Sampled','In Progress')) or (p_scope = 'wishlist' and ownership = 'Wishlist'))) then raise exception 'GAME_NOT_PINNABLE'; end if;
 if exists (select 1 from public.user_game_pins where user_id=p_user_id and scope=p_scope and game_id=p_game_id) then
 select coalesce(array_agg(game_id order by slot),array[]::uuid[]) into result from public.user_game_pins where user_id=p_user_id and scope=p_scope; return result;
 end if;
 select candidate::smallint into next_slot from generate_series(1,3) candidate where not exists (select 1 from public.user_game_pins where user_id=p_user_id and scope=p_scope and slot=candidate) order by candidate limit 1;
 if next_slot is null then
 select slot into replace_slot from public.user_game_pins where user_id=p_user_id and scope=p_scope and game_id=p_replace_game_id;
 if replace_slot is null then raise exception 'PIN_LIMIT_REACHED'; end if;
 delete from public.user_game_pins where user_id=p_user_id and scope=p_scope and game_id=p_replace_game_id;
 next_slot := replace_slot;
 end if;
 insert into public.user_game_pins(user_id,game_id,scope,slot) values(p_user_id,p_game_id,p_scope,next_slot);
 select coalesce(array_agg(game_id order by slot),array[]::uuid[]) into result from public.user_game_pins where user_id=p_user_id and scope=p_scope;
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_pinned_steam_playtime(p_user_id uuid, p_games jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare changed integer; matched integer;
begin
 if not exists(select 1 from public.app_accounts where id=p_user_id) then
 raise exception 'INVALID_PLAYTIME_ACCOUNT';
 end if;
 if p_games is null or jsonb_typeof(p_games)<>'array' then
 raise exception 'INVALID_PLAYTIME_PAYLOAD';
 end if;
 if jsonb_array_length(p_games)>100 then raise exception 'PLAYTIME_BATCH_TOO_LARGE'; end if;
 if exists(select 1 from jsonb_to_recordset(p_games) as x(steam_appid text,minutes numeric)
 where steam_appid is null or steam_appid !~ '^[1-9][0-9]*$'
 or minutes is null or minutes<0 or minutes>2147483647 or minutes<>trunc(minutes)) then
 raise exception 'INVALID_PLAYTIME_GAME';
 end if;
 -- Same account lock as full imports. Never reset hours_at_pin or player edits.
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
 -- Pin actions delete these rows; serialize with unpins while the request saves.
 perform 1 from public.user_game_pins where user_id=p_user_id and scope='library' for share;
 select count(*) into matched from public.user_games g
 where g.user_id=p_user_id and g.ownership='Owned'
 and exists(select 1 from public.user_game_pins p where p.user_id=p_user_id and p.scope='library' and p.game_id=g.id)
 and exists(select 1 from jsonb_to_recordset(p_games) as x(steam_appid text)
 where x.steam_appid::bigint=g.catalog_steam_appid);

 with input as (
 select steam_appid::bigint as appid,round(round(max(minutes)/60,1)*60)::integer as minutes,
 max(case when last_played_at <= now()+interval '5 minutes' then last_played_at end) as played_at
 from jsonb_to_recordset(p_games) as x(steam_appid text,minutes numeric,last_played_at timestamptz)
 group by steam_appid::bigint
 ), updated as (
 update public.user_games g set
 hours_played=greatest(g.hours_played,round(x.minutes::numeric/60,1)),
 observed_playtime_minutes=greatest(g.observed_playtime_minutes,x.minutes),
 last_played_at=greatest(g.last_played_at,x.played_at),
 last_observed_played_at=case
 when g.observed_playtime_minutes is not null and x.minutes>g.observed_playtime_minutes then now()
 when x.played_at>coalesce(g.last_observed_played_at,'-infinity'::timestamptz) then x.played_at
 else g.last_observed_played_at end,
 recency_source=case
 when g.observed_playtime_minutes is not null and x.minutes>g.observed_playtime_minutes then 'observed_playtime_change'
 when x.played_at>coalesce(g.last_observed_played_at,'-infinity'::timestamptz) then 'steam_exact'
 else g.recency_source end,
 recency_evidence_at=case
 when (g.observed_playtime_minutes is not null and x.minutes>g.observed_playtime_minutes)
 or x.played_at>coalesce(g.last_observed_played_at,'-infinity'::timestamptz) then now()
 else g.recency_evidence_at end
 from input x
 where g.user_id=p_user_id and g.ownership='Owned' and g.catalog_steam_appid=x.appid
 and exists(select 1 from public.user_game_pins p where p.user_id=p_user_id and p.scope='library' and p.game_id=g.id)
 and (round(x.minutes::numeric/60,1)>g.hours_played
 or g.observed_playtime_minutes is null or x.minutes>g.observed_playtime_minutes
 or x.played_at>coalesce(g.last_played_at,'-infinity'::timestamptz))
 returning g.id
 ) select count(*) into changed from updated;
 -- A partial pin read is NOT a fresh whole-library daily snapshot.
 return jsonb_build_object('pinned_games_updated',changed,'pinned_games_matched',matched);
end;
$function$

CREATE OR REPLACE FUNCTION public.replace_guest_catalogue_pool(p_appids bigint[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_count integer;
begin
 if p_appids is null or cardinality(p_appids) = 0 then
 raise exception 'EMPTY_GUEST_POOL';
 end if;

 -- `where true` because the authenticator role preloads safeupdate, which rejects
 -- a DELETE with no WHERE clause. Without it this line failed every nightly
 -- steam-tags run from 2026-09-04, and the pool stopped refreshing after
 -- 2026-08-25.
 delete from public.guest_catalogue_pool where true;

 insert into public.guest_catalogue_pool (steam_appid, position)
 select appid, ordinality::integer
 from unnest(p_appids) with ordinality as t(appid, ordinality)
 -- Skip anything that has since left the catalogue rather than failing the
 -- whole refresh over one missing row.
 where exists (select 1 from public.catalog_games c where c.steam_appid = t.appid)
 on conflict (steam_appid) do nothing;

 get diagnostics v_count = row_count;
 return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_user_game_review(p_user_id uuid, p_game_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_updated integer;
begin
 if p_user_id is null then
 raise exception 'INVALID_REVIEW_USER';
 end if;
 if p_game_ids is null or cardinality(p_game_ids) = 0 then
 return 0;
 end if;
 if cardinality(p_game_ids) > 500 then
 raise exception 'REVIEW_BATCH_TOO_LARGE';
 end if;

 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));

 update public.user_games
 set review_requested_at = now(),
 updated_at = now()
 where user_id = p_user_id
 and id = any(p_game_ids)
 and ownership = 'Owned'
 -- A completed or sleeping game is not waiting on a decision; those are
 -- changed from the Library, not flagged back into a review queue.
 and status in ('Not Started', 'Sampled', 'In Progress');

 get diagnostics v_updated = row_count;
 return v_updated;
end;
$function$

