CREATE OR REPLACE FUNCTION public.sync_duration_estimate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 old_app_id bigint;
 new_app_id bigint;
 old_igdb_id bigint;
 new_igdb_id bigint;
 affected record;
 estimate_removed boolean;
begin
 if tg_op <> 'INSERT' then
 old_app_id := old.steam_app_id;
 if old.provider = 'igdb' then
 old_igdb_id := old.provider_game_id;
 end if;
 end if;

 if tg_op <> 'DELETE' then
 new_app_id := new.steam_app_id;
 if new.provider = 'igdb' then
 new_igdb_id := new.provider_game_id;
 end if;
 end if;

 -- Direct IGDB eligibility is a cross-row uniqueness decision. Serialize all
 -- IGDB identity changes so concurrent workers cannot each project a shared
 -- provider ID while the other transaction is still invisible. IGDB writes
 -- are infrequent enough that the deliberately coarse transaction lock is a
 -- safer trade-off than per-ID row-trigger locks (which can deadlock when two
 -- multi-row statements encounter IDs in opposite orders). Duration writers
 -- use PostgreSQL's default READ COMMITTED isolation so the SPI queries after
 -- a blocked lock acquisition see the transaction that just committed.
 if old_igdb_id is not null or new_igdb_id is not null then
 perform pg_catalog.pg_advisory_xact_lock(
 pg_catalog.hashtextextended('vaultshuffle:duration:igdb-writes', 0)
 );
 end if;

 for affected in
 select distinct candidates.steam_app_id
 from (
 select old_app_id as steam_app_id
 union all
 select new_app_id
 union all
 select estimate.steam_app_id
 from public.game_duration_estimates as estimate
 where estimate.provider = 'igdb'
 and estimate.match_status = 'matched'
 and estimate.provider_game_id is not null
 and estimate.provider_game_id in (old_igdb_id, new_igdb_id)
 ) as candidates
 where candidates.steam_app_id is not null
 order by candidates.steam_app_id
 loop
 estimate_removed := (
 (tg_op = 'DELETE' and affected.steam_app_id = old_app_id)
 or (
 tg_op = 'UPDATE'
 and old_app_id is distinct from new_app_id
 and affected.steam_app_id = old_app_id
 )
 );
 perform public.reconcile_catalogue_duration(
 affected.steam_app_id,
 estimate_removed
 );
 end loop;

 if tg_op = 'DELETE' then
 return old;
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trigger_popular_catalogue_enrichment_worker(p_worker text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'net', 'vault', 'cron'
AS $function$
declare
 has_active_work boolean;
 worker_job_name text;
 worker_secret text;
 request_id bigint;
begin
 case p_worker
 when 'catalogue-metadata' then
 worker_job_name := 'drain-popular-steam-20260820';
 select exists (
 select 1
 from public.catalog_ingest_queue job
 where job.source_payload ->> 'source' = 'popular_catalogue_2026-08-20'
 and job.status in ('pending', 'processing')
 ) into has_active_work;
 when 'durations' then
 worker_job_name := 'drain-popular-durations-20260820';
 select exists (
 select 1
 from public.game_duration_jobs job
 join public.catalog_ingest_queue batch on batch.steam_appid = job.steam_app_id
 where batch.source_payload ->> 'source' = 'popular_catalogue_2026-08-20'
 and job.status in ('pending', 'retry', 'processing')
 ) into has_active_work;
 else
 raise exception 'Unsupported enrichment worker: %', p_worker;
 end case;

 if not has_active_work then
 perform cron.unschedule(worker_job_name);
 return null;
 end if;

 select decrypted_secret
 into worker_secret
 from vault.decrypted_secrets
 where name = 'vaultshuffle_cron_secret';

 if worker_secret is null then
 raise exception 'Supabase Vault secret vaultshuffle_cron_secret is missing';
 end if;

 select net.http_get(
 url := format('https://vaultshuffle.com/api/cron/%s', p_worker),
 headers := jsonb_build_object(
 'Authorization', 'Bearer ' || worker_secret,
 'Accept', 'application/json'
 ),
 timeout_milliseconds := 300000
 ) into request_id;

 return request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.undo_user_purge_decision(p_user_id uuid, p_review_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 saved_review public.purge_reviews;
 ignored_game public.user_games;
 ignored_state jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));

 select *
 into saved_review
 from public.purge_reviews
 where id = p_review_id
 and user_id = p_user_id
 for update;

 if saved_review.id is null then
 return false;
 end if;

 if saved_review.action = 'pin' then
 ignored_state := public.apply_user_vault_action(
 p_user_id,
 'unpinned',
 saved_review.game_id,
 '{}'::jsonb
 );
 elsif saved_review.action in ('sleep', 'complete') then
 ignored_game := public.restore_user_game_active(
 p_user_id,
 saved_review.game_id
 );
 end if;

 delete from public.purge_reviews
 where id = p_review_id
 and user_id = p_user_id;

 return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.unpin_scoped_user_game(p_user_id uuid, p_game_id uuid, p_scope text DEFAULT 'library'::text)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result uuid[];
begin
 if p_scope not in ('library','wishlist') then raise exception 'INVALID_PIN_SCOPE'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text || ':' || p_scope,0));
 delete from public.user_game_pins where user_id=p_user_id and scope=p_scope and game_id=p_game_id;
 select coalesce(array_agg(game_id order by slot),array[]::uuid[]) into result from public.user_game_pins where user_id=p_user_id and scope=p_scope;
 return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.upsert_user_family_games(p_user_id uuid, p_games jsonb)
 RETURNS SETOF user_games
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if p_user_id is null or not exists (
 select 1 from public.app_accounts where id = p_user_id
 ) then
 raise exception 'INVALID_IMPORT_USER';
 end if;

 if p_games is null or jsonb_typeof(p_games) <> 'array' then
 raise exception 'INVALID_IMPORT_PAYLOAD';
 end if;

 if jsonb_array_length(p_games) > 500 then
 raise exception 'IMPORT_BATCH_TOO_LARGE';
 end if;

 if exists (
 select 1
 from jsonb_to_recordset(p_games) as input(steam_appid text)
 where input.steam_appid is null
 or input.steam_appid !~ '^[1-9][0-9]*$'
 ) then
 raise exception 'INVALID_IMPORT_GAME';
 end if;

 if exists (
 select 1
 from jsonb_to_recordset(p_games) as input(steam_appid text)
 left join public.catalog_games catalog
 on catalog.steam_appid = input.steam_appid::bigint
 where catalog.steam_appid is null
 ) then
 raise exception 'MISSING_CATALOG_GAME';
 end if;

 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));

 return query
 insert into public.user_games (
 user_id,
 catalog_steam_appid,
 ownership,
 status,
 hours_played,
 completion_percentage,
 date_added,
 notes,
 access_source,
 family_owner_steam_id,
 family_verified_at
 )
 select
 p_user_id,
 catalog.steam_appid,
 -- 'Owned' here means "on the shelf", which is what every read model filters
 -- on. What the player actually paid for is access_source, and that is what
 -- the money and value figures read.
 'Owned',
 'Not Started',
 -- Never the owner's hours. Zero plus access_source = 'family' is how the
 -- application knows it has not been told rather than being told zero.
 0,
 0,
 to_char(now(), 'DD/MM/YYYY'),
 '',
 'family',
 input.family_owner_steam_id,
 now()
 from jsonb_to_recordset(p_games) as input(
 steam_appid text,
 family_owner_steam_id text
 )
 join public.catalog_games catalog
 on catalog.steam_appid = input.steam_appid::bigint
 on conflict (user_id, catalog_steam_appid) do update set
 access_source = case
 when public.user_games.access_source = 'owned' then 'owned'
 else 'family'
 end,
 family_owner_steam_id = case
 when public.user_games.access_source = 'owned' then public.user_games.family_owner_steam_id
 else coalesce(excluded.family_owner_steam_id, public.user_games.family_owner_steam_id)
 end,
 family_verified_at = case
 when public.user_games.access_source = 'owned' then public.user_games.family_verified_at
 else now()
 end,
 ownership = case
 when public.user_games.access_source = 'owned' then public.user_games.ownership
 else 'Owned'
 end,
 updated_at = now()
 returning public.user_games.*;
end;
$function$
